-- Chicken by kind and by part (growth pass, 2026-11-23). Two new subcategories under Fish, meat & eggs. Broiler = USDA broilers or fryers; layer = USDA
-- stewing hen (the older laying bird); sonali and deshi have no USDA entry and carry no nutrition numbers. Parts and offal are read from USDA by
-- FoodData Central id (source_ref). Generated by database/tools/growth_catalog3.py. Idempotent. Run by migration 0050 and the seeder.

UPDATE foods f SET subcategory_id = s.id FROM food_subcategories s JOIN food_categories c ON c.id = s.category_id WHERE c.slug = 'proteins' AND s.slug = 'chicken-kinds' AND f.slug = 'broiler-chicken' AND f.subcategory_id IS NULL;
